entries[97070] = { ["name"] = "Flammenstoß", ["text"] = "30% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 637 Feuerschaden und zusätzlich im Verlauf von 8 Sek. 48 Feuerschaden zufügt." }
