entries[97074] = { ["name"] = "Ring des Frosts", ["text"] = "7% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nBeschwört im ausgewählten Gebiet einen Frostzirkel, der 3 Sek. benötigt, um sich vollständig zu schließen. Gegner, die den vollständig geschlossenen Zirkel betreten, werden 10 Sek. lang eingefroren. Der Zirkel hält 12 Sek. lang an und hat einen Radius von 10 Metern." }
entries[97076] = { ["name"] = "Erdbeben", ["text"] = "60% von Grundmana 35 Meter Reichweite\nWirken in 2.5 sek. 10 sek. Abklingzeit\nIhr lasst die Erde am Zielort beben und brechen. Feinden in einem Umkreis von 8 Metern wird alle 1 Sek. 325 körperlicher Schaden zugefügt, mit einer Chance von 10 %, betroffene Ziele umzuwerfen. Hält 10 Sek. lang an." }
